class TestCase_3(ATTestCase.TestCase):
    testCaseDesc = "Record the physical-link-bearing ports from the .setup file's [portlink] section (the test port, the partner port and any other linked ports). On each, issue 'shutdown' one at a time; after each port is shut down, read 'show interface <port> status' and ping the loopback address from the DUT."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33241, 9002.33241.3'
    testCaseMethod = "Record the physical-link-bearing ports from the .setup file's [portlink] section (the test port, the partner port and any other linked ports). On each, issue 'shutdown' one at a time; after each port is shut down, read 'show interface <port> status' and ping the loopback address from the DUT.\n"
    testCaseMethod += "Verify: For each shutdown port, its status row does NOT read 'connected'. After every individual shutdown the ping to the loopback address still receives replies with 0% loss and 'show ip interface brief' still lists the loopback address.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        loop_cidr = '10.33.241.1/32'
        dut.mode(')#')
        dut.cmd('interface lo')
        dut.cmd('ip address {}'.format(loop_cidr))
        dut.mode('#')

    def main(self):
        # legacy 5049_validation_example/test-5049.2001.py lines 117-145
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        self.log("STEP 5: Record the physical-link-bearing ports from the .setup file's [portlink] section (the test port, the partner port and any other linked ports). On each, issue 'shutdown' one at a time; after each port is shut down, read 'show interface <port> status' and ping the loopback address from the DUT.")
        loop_addr = '10.33.241.1'
        link_ports = [port for port in (portA, portPeer) if port is not None]
        if not link_ports:
            output = 'no link ports bound'
            self.log('OBSERVED: {}'.format(output))
            self.failed('No physical-link-bearing ports were bound by init()')
            return
        self.log('Recorded link ports: {}'.format(', '.join(port.name for port in link_ports)))
        output = ''
        for port in link_ports:
            name = port.name
            dut.mode(')#')
            dut.cmd('interface {}'.format(name))
            dut.cmd('shutdown')
            dut.mode('#')
            status_out = dut.cmd('show interface {} status'.format(name))
            ping_out = dut.cmd('ping {} repeat 5'.format(loop_addr))
            brief_out = dut.cmd('show ip interface brief')
