    testCaseMethod += 'Verify: The capture at the far end shows ICMP echo request packets whose IPv4 source address equals the loopback address and whose destination is the far-end address. (If the far end has a return route to the loopback, echo replies are also seen; the source-address check is the pass criterion.)\n'

    loAddr = '192.0.2.33'

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
